@startuml

class Doctor {
  + PractitionerNumber : string
  + FullName : string
  + Address : string
  + PhoneNumber : string
  + Signature : string
}

class Patient {
  + HealthNumber : string
  + FirstName : string
  + LastName : string
  + DateOfBirth : date
  + Address : string
  + PhoneNumber : string
}

class Requisition {
  + ValidFrom : date
  + RepetitionCount : int
  + RepetitionInterval : Interval
}

enum Interval {
  WEEKLY
  MONTHLY
  HALF_YEARLY
  YEARLY
}

class Test {
  + Name : string
  + Duration : int
  + IsWalkInOnly : boolean
  + RequiresSampleDropOff : boolean
}

class TestGroup {
  + Name : string
}

class Result {
  + IsPositive : boolean
  + Report : string
}

class Lab {
  + Address : string
  + RegistrationNumber : string
  + BusinessHoursStart : time
  + BusinessHoursEnd : time
  + CancellationFee : float
}

class Appointment {
  + ConfirmationNumber : string
  + Date : date
  + StartTime : time
  + EndTime : time
}

Doctor "1" -- "*" Requisition : prescribes
Patient "1" -- "*" Requisition : is subject of
Requisition "1" *-- "1..*" Test : contains
Test "*" -- "1" TestGroup : belongs to
Requisition "0..1" -- "0..1" Appointment : has
Patient "1" -- "*" Appointment : books
Lab "1" -- "*" Appointment : hosts
Lab "1" -- "*" Test : offers
Test "1" -- "0..*" Result : has
Requisition "1" -- "0..*" Result : produces
Doctor "0..1" -- "*" Result : views
Patient "1" -- "*" Result : views

@enduml

